IO=[('P1_PRESS','Сорғы 1: қысым','AI','AI0.0','ШУ-1','W12'),('P1_RUN_CMD','Сорғы 1: қосу командасы','DO','DO0.0','ШУ-1','W13'),('P1_RUN_FB','Сорғы 1: жұмыста','DI','DI0.0','ШУ-1','W14'),('P1_FAULT','Сорғы 1: авария','DI','DI0.1','ШУ-1','W15')]
