def grp(y,h,title,lines,c='bx'):
    o=R(10,y,320,h,c,5)+T(170,y+17,title,'t-s t-b')
    for i,l in enumerate(lines):o+=T(170,y+34+i*15,l,'t-s')
    return o
def fig_groups():
    o=grp(4,52,'Процесс пен логика',['Функционалдық сұлба · алгоритм сипаттамасы'])
    o+=grp(64,68,'Жабдық пен сымдар',['Құрылымдық сұлба · жабдық спецификациясы','Шкаф сұлбалары · кабель журналы'])
    o+=grp(140,84,'Сигнал мен деректер',['I/O тізімі · адрес кестесі','Modbus регистр картасы · желілік топология','SCADA экрандарының тізімі'],'bxa')
    return S(340,230,o,'Құжаттардың үш тобы: процесс пен логика; жабдық пен сымдар; сигнал мен деректер')
f_groups=F(fig_groups(),'Он бір құжаттың үш топқа бөлінуі (оқу ыңғайы үшін)')

