def fig_chain():
    st=[('Датчик өлшейді','2–3'),('PLC алгоритмді орындайды','4'),('RS-485 / Ethernet арқылы','5–7'),('SCADA тегі','6, 8'),('Экран, дабыл, архив, есеп','9, 11, 12'),('Оператор командасы','10')]
    o=''
    for i,(t,n) in enumerate(st):
        y=4+i*34;o+=T(30,y+16,n,'t-s ac')+B(62,y,178,24,t,'bxa' if i in(0,5) else 'bx','t-s',4)
        if i<5:o+=A(151,y+24,151,y+34)
    o+=B(250,4,86,190,'ПНР және\nқұжаттама\nтексереді\n(13, 15)\n\nқорғау\n(14)','bx','t-s',5)
    o+=T(170,222,'сол жақтағы сандар — сабақ нөмірлері','t-s mu')
    return S(340,230,o,'Курстың толық тізбегі: датчик, PLC, байланыс арнасы, SCADA тегі, экран мен дабыл, оператор командасы; ПНР мен құжаттама барлығын тексереді, ал қорғау бүкіл тізбекке қатысты')
f_chain=F(fig_chain(),'Курстың бір тізбегі: параметрден оператор командасына дейін')

def fig_pump():
    o=B(60,4,220,28,'Жаңа сорғы қосылды','bxa','t-s t-b',4)+A(170,32,170,48)
    o+=R(4,48,332,138,'bx',6)+T(170,66,'бірдей жаңартылады','t-s t-b')
    nm=['I/O тізімі','Электр сұлбасы','PLC бағдарламасы','Modbus / тег адресі','SCADA экраны','Дабыл параметрі']
    for i,t in enumerate(nm):
        x=12+166*(i%2);y=76+36*(i//2);o+=B(x,y,150,28,t,'bx','t-s',4)
    o+=T(170,206,'бір құжатты өзгерту жеткіліксіз','t-s ac')
    return S(340,216,o,'Жаңа сорғы қосылғанда I/O тізімі, электр сұлбасы, PLC бағдарламасы, Modbus немесе тег адресі, SCADA экраны және дабыл параметрі бірдей жаңартылады')
f_pump=F(fig_pump(),'Жаңа сорғы: алты құжат бір мезгілде жаңартылады')

